package com.example.mareasv7.data
import kotlinx.coroutines.*; import java.time.*; import java.time.format.DateTimeFormatter; import java.time.temporal.ChronoUnit; import kotlin.math.*
class Repository { private val z=ZoneId.of("Europe/Madrid")
 suspend fun load(lat:Double,lon:Double):Data=coroutineScope { val st=Api.ihm.stations().estaciones.puertos.minByOrNull{dist(lat,lon,it.lat.toDouble(),it.lon.toDouble())}?:error("Sin estación IHM"); val now=ZonedDateTime.now(z).withSecond(0).withNano(0); val fmt=DateTimeFormatter.ofPattern("yyyyMMdd"); val a=async{Api.ihm.tides(id=st.id,date=now.toLocalDate().format(fmt))}; val b=async{Api.ihm.tides(id=st.id,date=now.toLocalDate().plusDays(1).format(fmt))}; val w=async{Api.weather.get(lat,lon)}; val m=async{Api.marine.get(lat,lon)}
  val ev=(listOf(a.await().mareas,b.await().mareas).flatMap{r->r.datos.marea.mapNotNull{event(it,r.fecha,now)}}).sortedBy{it.offset}; val anchors=ev.filter{it.offset in -12.0..36.0}.map{it.offset to it.height}; if(anchors.size<4) error("Datos IHM insuficientes"); val curve=(0..96).map{Point(it/4.0,interp(anchors,it/4.0))}; val wr=w.await(); val mc=m.await().current; val h=wr.hourly; val temp24=hourly(h?.time,h?.temperature_2m,now); val uv24=hourly(h?.time,h?.uv_index,now); val wind24=hourly(h?.time,h?.wind_speed_10m,now); val gust24=hourly(h?.time,h?.wind_gusts_10m,now); val c=coefficient(now.toLocalDate()); Data("${st.puerto} (IHM ${st.id})",lat,lon,curve,ev.filter{it.offset in 0.0..24.0},interp(anchors,0.0),interp(anchors,.1)>=interp(anchors,0.0),wr.current?.temperature_2m?:0.0,wr.current?.apparent_temperature?:0.0,wr.current?.relative_humidity_2m?:0,wr.current?.surface_pressure?:0.0,wr.current?.uv_index?:0.0,wr.current?.wind_speed_10m?:0.0,wr.current?.wind_direction_10m?:0.0,wr.current?.wind_gusts_10m?:0.0,mc?.wave_height?:0.0,mc?.wave_period?:0.0,mc?.wave_direction?:0.0,mc?.swell_wave_height?:0.0,mc?.sea_surface_temperature?:0.0,temp24,uv24,wind24,gust24,c,moon(c)) }
 private fun event(e:IhmEvent,d:String?,now:ZonedDateTime):TideEvent?{val date=parseDate(e.fecha?:d?:return null)?:return null;val time=runCatching{LocalTime.parse(e.hora,DateTimeFormatter.ofPattern("H:mm"))}.getOrNull()?:return null;val l=LocalDateTime.of(date,time).atZone(ZoneOffset.UTC).withZoneSameInstant(z);return TideEvent(l.toLocalTime().format(DateTimeFormatter.ofPattern("HH:mm")),e.tipo,e.altura,ChronoUnit.MINUTES.between(now,l)/60.0)}
 private fun parseDate(v:String)=listOf("yyyy-MM-dd","dd/MM/yyyy","dd-MM-yyyy").firstNotNullOfOrNull{runCatching{LocalDate.parse(v.substringBefore("T"),DateTimeFormatter.ofPattern(it))}.getOrNull()}
 private fun hourly(t:List<String>?,v:List<Double>?,now:ZonedDateTime)=t.orEmpty().zip(v.orEmpty()).mapNotNull{(s,y)->runCatching{val x=ChronoUnit.MINUTES.between(now,LocalDateTime.parse(s).atZone(z))/60.0;if(x in 0.0..24.0)Point(x,y)else null}.getOrNull()}
 private fun interp(p:List<Pair<Double,Double>>,x:Double):Double{val q=p.zipWithNext().firstOrNull{x>=it.first.first&&x<=it.second.first}?:return p.last().second;val f=((x-q.first.first)/(q.second.first-q.first.first)).coerceIn(0.0,1.0);return q.first.second+(q.second.second-q.first.second)*(1-cos(PI*f))/2}
 private fun dist(a:Double,b:Double,c:Double,d:Double):Double{val p=Math.toRadians(c-a);val q=Math.toRadians(d-b);val x=sin(p/2).pow(2)+cos(Math.toRadians(a))*cos(Math.toRadians(c))*sin(q/2).pow(2);return 12742*asin(sqrt(x))}
 private fun coefficient(d:LocalDate):Int{val ref=LocalDate.of(2024,1,11);val phase=((ChronoUnit.DAYS.between(ref,d)%30+30)%30)/29.53;return (35+75*abs(cos(phase*2*PI))).roundToInt()};private fun moon(c:Int)=if(c>85)"Marea viva" else if(c<55)"Marea muerta" else "Marea media" }
